    cal: '<rect x="3.5" y="5" width="17" height="15" rx="3"/><path d="M3.5 10h17M8 3v4M16 3v4M7.5 14h3M13.5 14h3M7.5 17h3"/>',
    ar: '<path d="M12 4v12M7 11l5 5 5-5"/><path d="M5 20h14"/>',
    ap: '<path d="M12 20V8M7 13l5-5 5 5"/><path d="M5 4h14"/>',
    plan: '<path d="M4 7h16M4 12h10M4 17h7"/><circle cx="18" cy="16" r="3"/>',
