    if (f0.minCash > lo) g += '<line class="minl" x1="' + L + '" x2="' + (W - R) + '" y1="' + y(f0.minCash) + '" y2="' + y(f0.minCash) + '"/><text class="ax minl-t" x="' + (W - R) + '" y="' + (y(f0.minCash) - 6) + '" text-anchor="end">' + (flows ? 'min. ' : 'Minimum ') + esc(keur(f0.minCash)) + '</text>';
